using System.Text.Json;
using LXMF;

namespace NomadNet.Tests;

// Actual primary f6b56044b42f6ca08dc99b3ecb9d965a8eb5edb2 save_qr output,
// generated by GenerateNomadNetQrVectors.py; disclosure and loaded source SHA in fixture.
[Trait("Category", "Unit")]
public sealed class NomadNetPaperQrTests
{
    [Fact]
    public void HalfBlocksPreserveEveryModuleAndExplicitBlackOnWhiteWithoutLeakingUri()
    {
        using var fixture = Fixture();
        Assert.Equal(1, fixture.RootElement.GetProperty("messageCount").GetInt32());
        Assert.True(Assert.Single(fixture.RootElement.GetProperty("ingested").EnumerateArray())
            .GetProperty("originator").GetBoolean());
        var uri = fixture.RootElement.GetProperty("uri").GetString()!;
        var symbol = LxPaperQr.Encode(uri);
        var display = NomadNetPaperQr.Display(uri);
        Assert.StartsWith("\u001b[30;47m", display);
        Assert.EndsWith("\u001b[0m", display);
        Assert.DoesNotContain(uri, display);
        var rows = display["\u001b[30;47m".Length..^"\u001b[0m".Length].Split('\n');
        Assert.Equal((symbol.Size + 1) / 2 + 1, rows.Length);
        Assert.Equal("", rows[^1]);
        for (var y = 0; y < symbol.Size; y++)
        {
            Assert.Equal(symbol.Size, rows[y / 2].Length);
            for (var x = 0; x < symbol.Size; x++)
                Assert.Equal(symbol[x, y], (y % 2 == 0)
                    ? rows[y / 2][x] is '█' or '▀'
                    : rows[y / 2][x] is '█' or '▄');
        }
        Assert.All(rows[^2], value => Assert.True(value is ' ' or '▀'));
    }

    [Fact]
    public void SoftwareExportAndDisplayRejectForeignInputAndObserveCancellation()
    {
        using var fixture = Fixture();
        var uri = fixture.RootElement.GetProperty("uri").GetString()!;
        Assert.Equal(LxPaperQr.Encode(uri).ToPng(), NomadNetPaperQr.Png(uri));
        Assert.Throws<FormatException>(() => NomadNetPaperQr.Display("https://example.invalid/"));
        using var canceled = new CancellationTokenSource();
        canceled.Cancel();
        Assert.ThrowsAny<OperationCanceledException>(() => NomadNetPaperQr.Display(uri, canceled.Token));
        Assert.ThrowsAny<OperationCanceledException>(() => NomadNetPaperQr.Png(uri, canceled.Token));
    }

    private static JsonDocument Fixture() => JsonDocument.Parse(typeof(NomadNetPaperQrTests).Assembly
        .GetManifestResourceStream("NomadNet.Tests.NomadNetQrVectors.json")!);
}
